docs/specs/schemas/rulith-agent-mcp-meta.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-agent-mcp-meta-v2.schema.json",
  "title": "Rulith Host-only MCP metadata (rulith/v2)",
  "description": "Gateway output only, never a model tool input or transcript. Session identity comes from the authenticated Mcp-Session-Id header. The optional client declaration is a compatibility signal, not authority; ordinary tools-only MCP Hosts can use ReadOperation without a private capability.",
  "type": "object",
  "additionalProperties": false,
  "required": ["agentId", "focusedRoots", "recovery"],
  "properties": {
    "agentId": { "type": "string", "minLength": 1 },
    "focusedRoots": { "type": "array", "items": { "$ref": "#/$defs/FocusPair" } },
    "boardRevision": { "type": "string", "minLength": 1 },
    "affectedCases": {
      "type": "array",
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 },
      "description": "Complete authoritative Case ids, not acceptance-root ids; absent for results that do not report a graph write. Never truncate silently."
    },
    "recovery": { "$ref": "#/$defs/Recovery" },
    "operationTarget": { "$ref": "#/$defs/OperationTarget" }
  },
  "$defs": {
    "ToolName": {
      "type": "string",
      "enum": ["OpenCase", "ApplyBatch", "ApplyAction", "CloseCase", "QueryBoard", "ReadArtifact", "ReadOperation"]
    },
    "OriginalTool": {
      "type": "string",
      "enum": ["OpenCase", "ApplyBatch", "ApplyAction", "CloseCase", "QueryBoard", "ReadArtifact"]
    },
    "RecoveryState": {
      "type": "string",
      "enum": ["none", "waiting", "result_ready", "reconciliation_required"]
    },
    "FocusPair": {
      "type": "object",
      "additionalProperties": false,
      "required": ["caseId", "root"],
      "properties": {
        "caseId": { "type": "string", "minLength": 1 },
        "root": { "type": "string", "minLength": 1 }
      }
    },
    "ClientCapabilities": {
      "type": "object",
      "additionalProperties": false,
      "required": ["operationRecovery"],
      "properties": { "operationRecovery": { "const": 1 } },
      "description": "Optional declaration in initialize.capabilities.experimental[\"rulith/v2\"]. It identifies this recovery contract but grants no right to execute, observe or claim a result. An explicit legacy rulith/v1 serialRecovery:1 declaration is incompatible with v2 adoption and must be refused rather than silently upgraded."
    },
    "OperationTarget": {
      "type": "object",
      "additionalProperties": false,
      "required": ["callRef", "tool"],
      "properties": {
        "callRef": { "type": "string", "minLength": 1 },
        "tool": { "$ref": "#/$defs/OriginalTool" }
      },
      "description": "Only on ReadOperation responses whose immutable observation selected an original call, including a current disclosure refusal. Echoes that read's fixed target, not the current pending slot. Omitted for an observation of none. Hosts compare it to their expected original identity before attributing recovered content; it is not authority and never enters model content or tool arguments."
    },
    "Recovery": {
      "type": "object",
      "additionalProperties": false,
      "required": ["state"],
      "properties": {
        "state": { "$ref": "#/$defs/RecoveryState" },
        "callRef": { "type": "string", "minLength": 1 },
        "tool": { "$ref": "#/$defs/OriginalTool" },
        "since": { "type": "string", "minLength": 1 },
        "retryAfterMs": { "type": "integer", "minimum": 0, "maximum": 9007199254740991 },
        "teaching": { "type": "string" }
      },
      "allOf": [
        {
          "if": { "properties": { "state": { "const": "none" } }, "required": ["state"] },
          "then": {
            "not": {
              "anyOf": [
                { "required": ["callRef"] },
                { "required": ["tool"] },
                { "required": ["since"] },
                { "required": ["retryAfterMs"] },
                { "required": ["teaching"] }
              ]
            }
          },
          "else": { "required": ["callRef", "tool"] }
        }
      ],
      "description": "Host-only progress and opaque callRef for the original call. ReadOperation selects it from authenticated state; the model never submits this reference. No handoff flag is needed because a separate public read always answers its own request."
    }
  }
}

docs/specs/schemas/rulith-artifact-read-.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-artifact-read-v1.schema.json",
  "title": "Immutable generated-result Artifact read contract",
  "description": "Gateway data-plane contract. Production ownership, Source off-machine/storage permission, current disclosure authorization and durable retention are checked separately; reading never creates a Case or changes Board state.",
  "$ref": "#/$defs/ReadArtifact",
  "$defs": {
    "ArtifactRef": {
      "type": "string",
      "pattern": "^art_[a-f0-9]{32}$",
      "description": "Service-minted opaque reference. Knowledge of it does not grant access; never a URL or filesystem path."
    },
    "ReadArtifact": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ref"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991,
          "default": 0
        },
        "maxBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991,
          "description": "Requested upper bound; omission uses the configured read budget, larger requests are rejected rather than enlarging that budget."
        }
      }
    },
    "ReadArtifactResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ref",
        "mediaType",
        "encoding",
        "data",
        "offset",
        "nextOffset",
        "totalBytes",
        "complete",
        "truncated"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "encoding": {
          "enum": [
            "utf8",
            "base64"
          ]
        },
        "data": {
          "type": "string"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "nextOffset": {
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            {
              "type": "null"
            }
          ]
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "complete": {
          "type": "boolean"
        },
        "truncated": {
          "type": "boolean"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "complete": {
                "const": true
              }
            },
            "required": [
              "complete"
            ]
          },
          "then": {
            "properties": {
              "nextOffset": {
                "type": "null"
              },
              "truncated": {
                "const": false
              }
            }
          },
          "else": {
            "properties": {
              "nextOffset": {
                "type": "integer",
                "minimum": 0,
                "maximum": 9007199254740991
              },
              "truncated": {
                "const": true
              }
            }
          }
        }
      ],
      "description": "Offsets and totalBytes count the original immutable bytes; utf8 chunks never split a code point, binary data is base64. Completion means this read reached object EOF, not Case completion. The server also checks offset advancement and byte counts."
    },
    "ArtifactPolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inlineBytes",
        "readBytes",
        "objectBytes",
        "totalBytes",
        "temporaryRetentionMs"
      ],
      "properties": {
        "inlineBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "readBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "objectBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "temporaryRetentionMs": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        }
      },
      "description": "Values are supplied by existing deployment/operator configuration. Source permission is independent; quotas do not grant off-machine storage or release retained data."
    },
    "ArtifactUpload": {
      "type": "object",
      "required": [
        "executionGrant",
        "mediaType",
        "digest",
        "payloadEncoding",
        "bytes"
      ],
      "additionalProperties": false,
      "description": "Private Worker upload on /work/artifact. bytes is canonical base64 transport encoding; digest covers decoded original bytes. Gateway derives ownership and actual Source from the current granted invocation, computes length, checks effective retention permission and budgets, and durably retains before returning a reference. No worker-supplied owner, Source, totalBytes or retained flag. Retry of the same producing invocation and digest returns the same immutable object reference; different bytes require a distinct reference under the same existing storage budgets. Empty/small results remain inline under policy. Producer wiring constraint: before any object byte leaves the producing machine the Worker must already hold an explicit authenticated off-machine permission from the actual Source record. Holding the bytes, knowing a Source name, or having reached the server is not that permission, and bytes already received are never treated as authorization. Gateway rechecks the current permission and the current lease before accepting and retaining, and refuses a missing permission by name rather than by a default policy lookup miss. The grant is signed with the authenticated Connection key, which the Worker also holds, so a valid signature proves only that this Connection wrote the token and is never on its own evidence that Core dispatched the invocation. Admission therefore starts from Core's own trusted dispatched record for that invocation, recomputes the request identity from the Source, Tool pin and lease in force now, requires it to equal the identity the grant states, and hashes the bytes actually received rather than trusting the declared digest. A mismatch is a named artifact_digest_mismatch refusal before deduplication, finalization, retention or reference return. The deduplication key uses the verified content digest, so a retry carrying different bytes cannot retrieve a prior reference by claiming its digest.",
      "properties": {
        "executionGrant": {
          "type": "string",
          "minLength": 1
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        },
        "payloadEncoding": {
          "const": "base64"
        },
        "bytes": {
          "type": "string",
          "pattern": "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$",
          "minLength": 4
        }
      }
    },
    "ArtifactUploadResult": {
      "type": "object",
      "required": [
        "ref",
        "mediaType",
        "encoding",
        "totalBytes",
        "digest"
      ],
      "additionalProperties": false,
      "description": "Gateway-computed immutable object metadata. Reading encoding is separate from upload transport encoding. Invalid UTF8 must never be silently replaced; serve original bytes as base64 or reject visibly.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "encoding": {
          "enum": [
            "utf8",
            "base64"
          ]
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        }
      }
    },
    "WorkerArtifactReference": {
      "type": "object",
      "required": [
        "ref"
      ],
      "additionalProperties": false,
      "description": "A Worker report may supply only a service-issued ref for that same granted invocation. Gateway resolves and replaces metadata before the Core report; a reference alone grants no permission.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        }
      }
    },
    "SourceUploadPermission": {
      "type": "object",
      "required": [
        "sourceRecordId",
        "permission",
        "upload"
      ],
      "additionalProperties": false,
      "description": "One off-machine upload decision for one actual Source record. Only an explicit granted permission admits Artifact object bytes. Ordinary bounded inline results and facts still leave the machine under the existing Tool and Source disclosure rules; this object-storage permission is neither their authorization nor a bypass of it. denied is a recorded refusal; absent means no permission record was found, including the Source-free case where sourceRecordId is empty, and it must be refused under its own name so that adding, renaming or normalizing a policy key can never turn the refusal into a silent allow. quota and budget are separate and grant nothing.",
      "properties": {
        "sourceRecordId": {
          "type": "string"
        },
        "permission": {
          "enum": [
            "granted",
            "denied",
            "absent"
          ]
        },
        "upload": {
          "type": "boolean"
        },
        "refusal": {
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ],
          "description": "The refusal identity the producing implementation must return when upload is false, and null when it is true. Naming the refusal is the point; a refusal that reads as an unconfigured lookup cannot be told apart from a missing rule."
        }
      }
    },
    "ReceiptArtifact": {
      "type": "object",
      "required": [
        "ref",
        "mediaType",
        "totalBytes",
        "digest"
      ],
      "additionalProperties": false,
      "description": "Protected Gateway-to-Core report metadata, resolved from an already durably retained object. Core commits the reference with its execution receipt; ExecutionResultVector carries this array into resultDigest. Worker self-authored metadata or cross-invocation/Source reuse is refused, and refusing a forged cross-invocation report never releases the retain the producing invocation legitimately holds. Because this shape has four fields, an array uniqueItems constraint over it only bars two identical objects: the same ref carrying two different sets of metadata satisfies uniqueItems and would still change the receipt digest, so uniqueness by ref belongs to the Gateway resolution step and must be refused there by name. An object the Core still references is not collectable, and an object that has not entered a proof may still carry an execution audit reference; return to temporary retention is allowed only once the authority confirms no reference and no pending retain request remains. Physical collection stays deferred, so nothing here starts an automatic sweep.",
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "digest": {
          "$ref": "#/$defs/Digest"
        }
      }
    },
    "Digest": {
      "type": "string",
      "pattern": "^sha256:[a-f0-9]{64}$"
    }
  }
}

docs/specs/schemas/rulith-board-query-co.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-query-context-v1.schema.json",
  "title": "Protected QueryBoard context",
  "description": "Set by Gateway from authenticated request context, never accepted as Agent tool input. Core validates audience against authenticated principal before reading nodes. Audience enum is checked against QueryBoard.audienceProfiles in operations.json.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "audienceProfile"
  ],
  "properties": {
    "audienceProfile": {
      "type": "string",
      "enum": [
        "agent",
        "operator",
        "internal"
      ]
    },
    "requestedRoots": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Acceptance-root ids, not case ids. Omitted or [] requests no additional root summaries; this never supplies an Agent selector.roots prerequisite."
    }
  },
  "$defs": {
    "AudienceAllowances": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "principals": {
          "type": "object",
          "additionalProperties": {
            "type": "array",
            "uniqueItems": true,
            "items": {
              "type": "string",
              "enum": [
                "agent",
                "operator",
                "internal"
              ]
            }
          }
        },
        "default": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "const": "agent"
          },
          "description": "Absence means the agent base allowance; operator/internal cannot be granted through a default."
        }
      }
    }
  }
}

docs/specs/schemas/rulith-board-v1.schem.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-v1.schema.json",
  "title": "Rulith Board Protocol v1 (rulith-board/1)",
  "description": "Normative artifact promised by protocol-spec section 3. RT-SCHEMA guards keep this Schema, the operation model, documentation, and the Rust advertisement aligned. Every command accepted by protocol conformance fixtures must validate against this Schema. Required fields are the wire-level fields whose absence the authoritative service rejects. Identity is not part of this Schema: principal, roles, and channelId are injected by authenticated transport and never accepted from the request body. The root shape is BoardCommand; responses and events are BoardResult and BoardEvent.",
  "$ref": "#/$defs/BoardCommand",
  "$defs": {
    "BoardCommand": {
      "description": "Command envelope. requestId provides idempotency. There is no caller-supplied concurrency pin: one Board holds one shared graph, a write is judged against the premises current at execution time, and which acceptance roots it reached is answered afterwards in BoardResult.affectedCases rather than declared beforehand. queryContext and admission are set by the Gateway from the authenticated request and are never accepted as model input. The envelope remains open for backward-compatible field additions, while each operation shape remains closed; the retired names listed in retiredEnvelopeFields are the exception, and they are refused rather than ignored.",
      "type": "object",
      "required": [
        "protocol",
        "boardId",
        "requestId",
        "operation"
      ],
      "additionalProperties": true,
      "allOf": [
        {
          "$ref": "#/$defs/RetiredEnvelopeFields"
        },
        {
          "$ref": "#/$defs/QueryContextRequiredForQueryBoard"
        },
        {
          "$ref": "#/$defs/AdmissionRequiredForOpenCaseCreate"
        }
      ],
      "properties": {
        "protocol": {
          "const": "rulith-board/1"
        },
        "locale": {
          "type": "string",
          "enum": [
            "en"
          ],
          "description": "Presentation language for this response. It affects teaching and presentation only and never enters closure, revision, or idempotency identity. Omitted means en. Any other value is rejected with bad_command; GetProtocolManifest.locales advertises the supported set."
        },
        "boardId": {
          "type": "string",
          "minLength": 1
        },
        "requestId": {
          "type": "string",
          "minLength": 1
        },
        "queryContext": {
          "$ref": "rulith-board-query-context-v1.schema.json",
          "description": "Protected read context, injected by the Gateway from the authenticated request. Referenced, never restated: the audience enum and the requestedRoots shape have one normative home, and a second copy here would be a second thing to keep in step. A network QueryBoard without it is refused before any node is read (audience_profile_required)."
        },
        "admission": {
          "$ref": "#/$defs/CaseAdmission",
          "description": "Gateway-authorized Case admission, injected from the authenticated request. Required on the OpenCase create form and ignored elsewhere; a create without it is refused."
        },
        "operation": {
          "$ref": "#/$defs/BoardOperation"
        }
      }
    },
    "CaseAdmission": {
      "description": "Commercial, Capability and program pins authorized before a Case is created. businessKeyDigest is required but nullable: null means a non-keyed exploration Case; absence is a missing commitment and is refused. A new creation also requires expectedProgramGeneration; its omission remains decodable only to retrieve a historical committed request's original receipt. Wrong-typed values are refused rather than coerced. Affinity is optional.",
      "type": "object",
      "required": [
        "capabilityReleaseDigest",
        "caseContractDigest",
        "businessKeyDigest",
        "commercialTermsDigest",
        "maxExplorationBps"
      ],
      "additionalProperties": false,
      "properties": {
        "expectedProgramGeneration": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991,
          "description": "Required to create a new Case: the active program generation observed before authorizing and reserving this admission. A mismatch refuses without minting identity. Omission can only return a previously committed historical request's original receipt, never create a new root."
        },
        "capabilityReleaseDigest": {
          "type": "string",
          "minLength": 1
        },
        "caseContractDigest": {
          "type": "string",
          "minLength": 1
        },
        "businessKeyDigest": {
          "type": [
            "string",
            "null"
          ],
          "description": "sha256 of the frozen business key, or an explicit null for a non-keyed exploration Case. Omitting the field is not the same as sending null and is refused."
        },
        "commercialTermsDigest": {
          "type": "string",
          "minLength": 1
        },
        "maxExplorationBps": {
          "type": "integer",
          "minimum": 0,
          "maximum": 65535,
          "description": "Wire domain is the u16 the authority parses into. The platform profile refuses anything above 1000 at OpenCase, with teaching; that is a policy ceiling and lives there, not in this type."
        },
        "affinityKey": {
          "type": "string",
          "minLength": 1,
          "description": "Optional routing hint. Absent means no affinity was requested."
        }
      }
    },
    "RetiredEnvelopeFields": {
      "description": "The envelope keys the authority refuses **by name**, listed here so this Schema refuses them too. Without this the envelope's additionalProperties:true would let every one of them validate, and a client generating requests from this artifact would keep sending a field the service rejects while the contract said it was fine. Ignoring them is the worst available behaviour and is why the authority refuses instead: a caller that sent case:{...} believes it scoped the command to one Case, and answering against the whole shared graph would be the widest possible read reported as a success; a caller that sent viewToken believes a freshness check ran. case, caseRevision and expectedRevision are gone with the per-Case namespace and its compare-and-set pin; viewToken and interaction.bootstrap are gone with the observation cursor. None has a replacement field — affectedCases answers the membership question afterwards. Other unknown keys stay permitted: this list closes exactly the names the authority closes, and closing more would be a rule nothing enforces.",
      "type": "object",
      "not": {
        "anyOf": [
          {
            "required": [
              "case"
            ]
          },
          {
            "required": [
              "caseRevision"
            ]
          },
          {
            "required": [
              "expectedRevision"
            ]
          },
          {
            "required": [
              "viewToken"
            ]
          },
          {
            "required": [
              "interaction"
            ],
            "properties": {
              "interaction": {
                "type": "object",
                "required": [
                  "bootstrap"
                ]
              }
            }
          }
        ]
      }
    },
    "QueryContextRequiredForQueryBoard": {
      "description": "A network QueryBoard must carry the protected read context. The authority refuses one that does not before it reads any node, and returns zero Board data — a default here would be a disclosure decision made by omission.",
      "type": "object",
      "if": {
        "type": "object",
        "required": [
          "operation"
        ],
        "properties": {
          "operation": {
            "type": "object",
            "required": [
              "kind"
            ],
            "properties": {
              "kind": {
                "const": "QueryBoard"
              }
            }
          }
        }
      },
      "then": {
        "required": [
          "queryContext"
        ]
      }
    },
    "AdmissionRequiredForOpenCaseCreate": {
      "description": "The OpenCase create form must carry the Gateway-authorized admission; the focus form must not need one, because returning to a Case re-uses the pins frozen when it opened. The two forms are told apart the same way the parser tells them apart: create names a caseType, focus names a caseId.",
      "type": "object",
      "if": {
        "type": "object",
        "required": [
          "operation"
        ],
        "properties": {
          "operation": {
            "type": "object",
            "required": [
              "kind",
              "caseType"
            ],
            "properties": {
              "kind": {
                "const": "OpenCase"
              }
            }
          }
        }
      },
      "then": {
        "required": [
          "admission"
        ]
      }
    },
    "BoardOperation": {
      "description": "v1 操作面(名单与 TS BoardOperation 联合类型逐项相等——数字不手写,RT-SCHEMA-1 执法)。",
      "oneOf": [
        {
          "$ref": "#/$defs/GetProjection"
        },
        {
          "$ref": "#/$defs/GetChanges"
        },
        {
          "$ref": "#/$defs/QueryBoard"
        },
        {
          "$ref": "#/$defs/GetBoardManifest"
        },
        {
          "$ref": "#/$defs/EvaluateCandidateShadow"
        },
        {
          "$ref": "#/$defs/ReadBillingOutbox"
        },
        {
          "$ref": "#/$defs/AcknowledgeBillingOutbox"
        },
        {
          "$ref": "#/$defs/RunDischarge"
        },
        {
          "$ref": "#/$defs/ApplyBatch"
        },
        {
          "$ref": "#/$defs/Explain"
        },
        {
          "$ref": "#/$defs/IngestObservation"
        },
        {
          "$ref": "#/$defs/RegisterPack"
        },
        {
          "$ref": "#/$defs/RemovePack"
        },
        {
          "$ref": "#/$defs/CreateBoard"
        },
        {
