docs/specs/schemas/rulith-operation-read.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-operation-read-v1.schema.json",
  "title": "Public original-operation read contract",
  "description": "ReadOperation locates the current Agent's original call from authenticated Host state. The caller supplies no call reference, request identity, tool name, authority claim or new business command. The first RPC binds its own transport identity to the original target and observed state; retrying that RPC repeats the same observation rather than selecting a later target. ReadOperation never becomes or replaces the pending business call. Current disclosure authorization is checked again for every result delivery. A successful ReadOperation has isError:false even when originalResult.isError is true; only an invalid or unauthorized ReadOperation itself is an error. A ready result is delivered and acknowledged only after the authorized projection of the terminal original call is available. Waiting and reconciliation never release the pending call. The Host can mechanically claim a ready result without QueryBoard.",
  "$ref": "#/$defs/ReadOperation",
  "$defs": {
    "ReadOperation": {
      "type": "object",
      "additionalProperties": false,
      "properties": {},
      "description": "Empty public input; the opaque callRef remains Host-only metadata."
    },
    "RecoveryState": {
      "type": "string",
      "enum": ["none", "waiting", "result_ready", "reconciliation_required"]
    },
    "OriginalTool": {
      "type": "string",
      "enum": ["OpenCase", "ApplyBatch", "ApplyAction", "CloseCase", "QueryBoard", "ReadArtifact"]
    },
    "PublicToolResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["content", "isError"],
      "properties": {
        "content": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["type", "text"],
            "properties": {
              "type": { "const": "text" },
              "text": { "type": "string" }
            }
          }
        },
        "structuredContent": {
          "type": "object",
          "not": {
            "anyOf": [
              { "required": ["_meta"] },
              { "required": ["rawReceipt"] },
              { "required": ["agentId"] },
              { "required": ["boardId"] }
            ]
          },
          "description": "Present only when the original public result already disclosed this content. The Gateway must project nested content under the same current disclosure rules; this shallow exclusion is not an authorization filter or a second Board result schema."
        },
        "isError": { "type": "boolean" }
      },
      "description": "The original tool's existing authorized public MCP result projection, not a deep copy of the original response. Never include original _meta, raw Core/Worker receipts, agentId, boardId or undisclosed business data. The original refusal stays nested here; it does not turn a successful ReadOperation into an error."
    },
    "ReadOperationResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["state"],
      "properties": {
        "state": { "$ref": "#/$defs/RecoveryState" },
        "originalTool": { "$ref": "#/$defs/OriginalTool" },
        "originalResult": { "$ref": "#/$defs/PublicToolResult" },
        "teaching": { "type": "string", "minLength": 1 }
      },
      "oneOf": [
        {
          "properties": { "state": { "const": "none" } },
          "not": { "anyOf": [ { "required": ["originalTool"] }, { "required": ["originalResult"] } ] }
        },
        {
          "properties": { "state": { "const": "waiting" } },
          "required": ["originalTool"],
          "not": { "required": ["originalResult"] }
        },
        {
          "properties": { "state": { "const": "result_ready" } },
          "required": ["originalTool", "originalResult"]
        },
        {
          "properties": { "state": { "const": "reconciliation_required" } },
          "required": ["originalTool", "teaching"],
          "not": { "required": ["originalResult"] }
        }
      ],
      "description": "Read status is separate from the original tool result. none has no original call; waiting and reconciliation preserve it without inventing a terminal result. result_ready contains the exact current authorized public projection of a terminal original call."
    }
  }
}

protocol/mcp-surface.json.content:
{
  "schema": "rulith-mcp-surface/v2",
  "protocolVersion": "2025-11-25",
  "description": "Public Agent tool membership and dispatch for operation recovery. Its existence does not attest that a running server has adopted it. Historical v1 bundles remain verifiable but cannot be adopted as this v2 surface. schemaRef values identify files from the Core repository root; vendors verify a source-path-to-bytes map against the named Git commit and resolve it without network access. Adopting Gateways serve each inputSchema directly from the verified rulith-mcp-contract-bundle/v1 tools entry, including its generated definition names and explicit dialect. Object key order and JSON whitespace are immaterial; independently regenerated schema shapes are not the delivered contract.",
  "metadata": {
    "namespace": "rulith/v2",
    "schemaRef": "docs/specs/schemas/rulith-agent-mcp-meta-v2.schema.json"
