      "target": "core",
      "operation": "CloseCase",
      "inputSchemaRef": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentCloseCase"
    },
    {
      "name": "QueryBoard",
      "target": "core",
      "operation": "QueryBoard",
      "inputSchemaRef": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentQueryBoard"
